def rag_messages(q, hits):
    ctx = '\n\n'.join(f'[{i+1}] {d}' for i, (_, d) in enumerate(hits))
    sys = ('아래 조각만 근거로 한국어로 짧게 답해. 조각에 없으면 "노트에 없어요"라고 해. '
           '답 끝에 쓴 조각 번호를 [1] 처럼 적어.')
    return [{'role': 'system', 'content': sys},
            {'role': 'user', 'content': f'{ctx}\n\n질문: {q}'}]

import json, re, datetime, os
import rag

TOOLS = {
  'today': {'desc': '오늘 날짜. args 없음', 'fn': lambda: datetime.date.today().isoformat()},
  'search_notes': {'desc': '내 노트 검색. args: {"q": 검색어}', 'fn': lambda q: [d[:300] for _, d in rag.search(q, k=3)]},
  'read_file': {'desc': 'notes/ 안의 파일 읽기. args: {"path": "notes/x.md"}', 'fn': lambda path: open(path, encoding='utf-8').read()[:3000]},
}
DANGEROUS = set()   # 예: {'write_file'}

def tool_prompt():
    lines = '\n'.join(f'- {n}: {t["desc"]}' for n, t in TOOLS.items())
    return ('도구가 필요하면 다른 말 없이 {"tool": 이름, "args": {...}} 한 줄만 써. '
            '필요 없으면 그냥 한국어로 짧게 답해.\n도구 목록:\n' + lines +
            '\n예: {"tool": "today", "args": {}}')

def parse_call(text):
    m = re.search(r'\{.*\}', text, re.S)
    if not m: return None
    try: c = json.loads(m.group(0))
    except json.JSONDecodeError: return 'BAD_JSON'
    return c if isinstance(c, dict) and 'tool' in c else None

def run(call):
    name, args = call['tool'], call.get('args') or {}
    if name not in TOOLS: return f'없는 도구: {name}. 목록에서 고르세요.'
    if name == 'read_file' and not os.path.realpath(args.get('path', '')).startswith(os.path.realpath('notes')):
        return 'notes/ 밖은 읽을 수 없어요'
    if name in DANGEROUS and input(f'{name}{args} 실행? y/n ') != 'y': return '사용자가 거절했어요'
    try: return TOOLS[name]['fn'](**args)
    except Exception as e: return f'도구 오류: {e}'

from faster_whisper import WhisperModel
_model = WhisperModel('small', device='cpu', compute_type='int8')

def transcribe(wav_path):
    segments, info = _model.transcribe(wav_path, language='ko')
    return ''.join(s.text for s in segments).strip()

import subprocess

def speak(text, voice='Yuna'):
    subprocess.run(['say', '-v', voice, '-r', '200', text[:400]])
